using ClinicManager.DAL;using ClinicManager.DTO;
namespace ClinicManager.BUS;
public sealed class ClinicService{public ClinicRepository Data{get;}=new();public void ValidatePatient(string name,string phone){if(string.IsNullOrWhiteSpace(name)||phone.Length<9)throw new InvalidOperationException("Nhập họ tên và số điện thoại hợp lệ.");}public void ValidateMedicine(string name,string unit,decimal price,int stock){if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(unit)||price<0||stock<0)throw new InvalidOperationException("Kiểm tra tên, đơn vị, giá và tồn kho.");}public void ValidateOrder(int visit,decimal fee,IReadOnlyList<PrescriptionLineDto> lines){if(visit<=0||fee<0||lines.Count==0)throw new InvalidOperationException("Chọn hồ sơ khám, nhập tiền khám và thêm thuốc.");}}
